// Learn tab. The waveform gallery is generated by running the engine, so the pictures are what this simulator really produces.
import { Sim } from './engine/engine.js';
import { drawStrip } from './draw.js';
import { ASYN } from './asyn.js';

const GALLERY = [
  { t: 'Volume control, square flow (normal lungs)', key: 'normal', set: { mode: 'VC', vt: 450, rr: 14, ti: 1.0, flow: 'square' },
    look: 'Flow is a flat box. Pressure ramps up in a straight line because compliance is constant, with a small step at the start from airway resistance. Flow returns to zero before the next breath.' },
  { t: 'Volume control with an inspiratory hold', key: 'normal', set: { mode: 'VC', vt: 450, rr: 14, ti: 1.0, flow: 'square', holdDur: 2 }, hold: true,
    look: 'During the hold flow is zero and pressure falls from peak to a plateau. Peak minus plateau is the resistive load; plateau minus PEEP over VT is compliance. Plateau keeps drifting down for seconds (viscoelastic relaxation), so quote the hold duration.' },
  { t: 'Pressure control (normal lungs)', key: 'normal', set: { mode: 'PC', pc: 15, rr: 14, ti: 1.0 },
    look: 'Pressure is a square box. Flow starts high and decelerates as the lung fills. Volume depends on compliance and resistance, so watch the exhaled volume, not the set pressure.' },
  { t: 'Pressure support with patient effort', key: 'normal', mods: { drive: { rate: 16, pmax: 6, tn: 1.0 } }, set: { mode: 'PSV', ps: 10, peep: 5 },
    look: 'Each breath starts with a small drop in pressure or a flow deflection (the trigger), then decelerating flow. The breath ends when flow falls to the cycle-off percentage of peak. Rate and breath size come from the patient.' },
  { t: 'High resistance: mucus plug or biting the tube', key: 'normal', mods: { ettMult: 10 }, set: { mode: 'VC', vt: 500, rr: 14, ti: 0.8, flow: 'square', holdDur: 1 }, hold: true,
    look: 'Peak pressure is high, plateau is normal, and the gap between them is wide. Expiratory flow is slow and may not reach zero.' },
  { t: 'Low compliance: pneumothorax, mainstem intubation, edema', key: 'normal', mods: { cMult: 0.25 }, set: { mode: 'VC', vt: 450, rr: 14, ti: 1.0, flow: 'square', holdDur: 1 }, hold: true,
    look: 'Peak and plateau are both high, with a normal gap. The pressure ramp is steeper. Expiration is fast because the stiff lung recoils briskly.' },
  { t: 'Auto-PEEP in COPD', key: 'copd', mods: { qmax: 0.10 }, set: { mode: 'VC', vt: 450, rr: 16, peep: 0, ti: 0.9, flow: 'square' },
    look: 'Expiratory flow is still going when the next breath starts (the flow trace never returns to zero). The baseline of the volume trace creeps up. This is dynamic hyperinflation: give more expiratory time.' },
  { t: 'Flow starvation and double triggering', key: 'normal', mods: { sex: 'M', weight: 80, vco2: 260, drive: { rate: 14, pmax: 14, tn: 1.2 } }, set: { mode: 'VC', vt: 400, rr: 12, ti: 0.5, flow: 'square' },
    look: 'The patient pulls against a fixed flow, so airway pressure sags or scoops during inspiration. When the ventilator cycles off before the patient has finished inspiring, a second breath follows at once (stacked breaths).' },
];

const SETTINGS = [
  ['Mode', 'How breaths are started, limited and ended. VC: you set volume and flow. PC: you set pressure and time. APVcmv: pressure control whose pressure is adjusted each breath to reach a target volume. SPONT (PSV/CPAP): the patient triggers and sets rate; the ventilator adds pressure support.'],
  ['Tidal volume (VT)', 'Volume delivered per breath. Set from predicted body weight (PBW, from sex and height), not actual weight: usually 6-8 mL/kg PBW, 4-6 in severe ARDS if plateau is high.'],
  ['Pressure above PEEP (PC)', 'Driving pressure that fills the lung in pressure control. Resulting volume = pressure x compliance (less if resistance or short Ti). Titrate to VT 6-8 mL/kg PBW.'],
  ['Pressure support (PSV)', 'Extra pressure on spontaneous breaths. Higher = more help and bigger breaths. 5-8 is a typical trial level; 10-20 for rest.'],
  ['Rate', 'Set breaths per minute. In assist-control a patient can breathe faster than this, never slower. Minute ventilation = VT x rate and controls PaCO2.'],
  ['Inspiratory time (Ti)', 'Length of inspiration. Sets I:E with rate. Normal about 0.8-1.2 s. Short Ti leaves long expiration (good in COPD/asthma); too short for a strong patient causes double triggering; long Ti in COPD stacks breaths.'],
  ['Flow pattern (VC)', 'Square: constant flow, easy to measure resistance and plateau. Decelerating: flow falls through inspiration, lower peak pressure, better gas distribution.'],
  ['PEEP', 'Pressure kept at end of expiration. Keeps alveoli open (oxygenation) and counters auto-PEEP threshold load. Too much overdistends and lowers blood pressure. Usual 5; ARDS higher.'],
  ['FiO2', 'Oxygen fraction. Use the lowest that meets the SpO2 target.'],
  ['Flow trigger', 'Inspiratory flow the patient must generate to start a breath. Lower = more sensitive; too low causes auto-triggering. Typical 2-5 L/min.'],
  ['Rise time', 'How fast pressure ramps up in pressure modes. A fast rise helps a strong patient; too fast gives a pressure overshoot.'],
  ['Cycle off', 'In PSV the breath ends when flow falls to this percentage of peak flow. Higher % = shorter breath (use in COPD), lower % = longer breath (restrictive).'],
  ['Hold duration', 'Length of the inspiratory or expiratory hold you request. Plateau is read at the end of the hold, so longer holds read slightly lower.'],
  ['Adaptive target volume (APVcmv)', 'In this mode the volume you set is a target, not a guarantee. Pressure is raised or lowered by at most 3 cmH2O per breath to reach it, bounded by the pressure limit. Watch the pressure trend: a rising pressure at a steady VT means compliance or resistance is getting worse.'],
  ['Effort rise, hold and decay', 'Shape of the patient\'s muscle pressure. Rise = how fast effort builds (a steep rise is high drive and shows up as a larger P0.1). Hold = time at peak effort. Decay = relaxation, which carries on into early expiration. Touching any of these switches the effort from a simple half-sine to this shaped waveform.'],
  ['Show Pmus (above the waveforms)', 'Draws the patient\'s muscle pressure as a dashed line on the pressure trace, so you can see effort that the ventilator did not respond to, and compare when effort starts and stops with when the ventilator cycles.'],
  ['Patient (lung type, sex, height, weight)', 'Normal, COPD or ARDS lungs. Height and sex give PBW. The tube size and kink slider change airway resistance. Patient effort rate and strength make the simulated patient breathe on their own (0 = sedated and passive).'],
];

const TARGETS = [
  ['Tidal volume', '6-8 mL/kg PBW (4-6 if severe ARDS and plateau > 30)'],
  ['Plateau pressure', 'At or below 30 cmH2O (needs a 0.5-1 s inspiratory hold in volume control)'],
  ['Driving pressure (plateau - PEEP)', 'Below about 15 cmH2O; lower is better in ARDS'],
  ['Peak pressure', 'Alarm around 35-40. Peak much higher than plateau means a resistance problem'],
  ['SpO2 / PaO2', 'SpO2 92-96% in most patients; 88-92% (PaO2 55-80) in ARDS and chronic hypercapnia'],
  ['pH / PaCO2', 'pH 7.30-7.45 for most; permissive hypercapnia to pH of about 7.20-7.25 is accepted in ARDS and severe obstruction. In chronic COPD judge by pH, not PaCO2'],
  ['I:E ratio', 'About 1:2 normally; 1:3 to 1:5 in COPD/asthma'],
  ['Auto-PEEP', 'Aim for under about 5 cmH2O; measure with an expiratory hold'],
  ['Respiratory rate', 'About 12-20 normally; 8-14 in obstruction; higher to compensate for acidosis or when VT is low in ARDS'],
  ['FiO2 and PEEP in ARDS (ARDSNet lower-PEEP table, condensed)', 'FiO2 0.3-0.4: PEEP 5-8. 0.5: 8-10. 0.6: 10. 0.7: 10-14. 0.8: 14. 0.9: 14-18. 1.0: 18-24'],
  ['SBT readiness', 'FiO2 up to 0.5, PEEP up to 8, hemodynamically stable, can trigger breaths. RSBI (rate / VT in litres) below about 105 favors success'],
];

const STRATEGIES = [
  ['Normal lungs (post-operative, neurological)', 'Assist-control, VT 6-8 mL/kg PBW, rate 12-16, PEEP 5, FiO2 to SpO2 92-96%, Ti about 1 s. Check an ABG after PaCO2 has had about 20 minutes to settle.'],
  ['ARDS', 'VT 6 mL/kg PBW, plateau at or below 30, driving pressure below 15. Raise PEEP stepwise while watching plateau, compliance and blood pressure. Accept pH down to about 7.20. If P/F stays under about 150 on FiO2 0.6 or more, consider prone positioning for 12-16 hours a day.'],
  ['COPD / asthma', 'Low rate (8-14), short Ti (0.7-1.0 s), decelerating or high flow, VT 6-8 mL/kg. Aim for a long expiratory time and expiratory flow that reaches zero. If auto-PEEP is present and the patient is triggering, add extrinsic PEEP at about 80% of it. Treat bronchospasm. Accept hypercapnia.'],
  ['Metabolic acidosis (DKA, sepsis)', 'The patient was compensating with a high minute ventilation. Match it (often rate 24-30 with VT 6-8 mL/kg). Winter formula: expected PaCO2 = 1.5 x HCO3 + 8, plus or minus 2.'],
  ['Weaning', 'Daily sedation interruption and readiness screen, then a 30-120 minute spontaneous breathing trial on PS 5-8 with PEEP 5 or T-piece. Watch rate, RSBI, SpO2, comfort.'],
  ['Alarm triage: DOPE', 'Displacement (tube position, mainstem), Obstruction (secretions, kink, biting), Pneumothorax, Equipment (circuit, ventilator). Disconnect and hand-bag if unstable. Then use the pressures: high peak with normal plateau = resistance; both high = compliance.'],
];

const FORMULAS = [
  ['Predicted body weight', 'Male 50 + 0.91 x (height cm - 152.4); female 45.5 + 0.91 x (height cm - 152.4). Height and sex only, not age or actual weight.'],
  ['Static compliance', 'VT / (plateau - total PEEP). Needs a passive patient and an inspiratory hold. Normal ventilated adult about 50-80 mL/cmH2O; ARDS often 20-35.'],
  ['Driving pressure', 'Plateau - total PEEP = VT / compliance. Lower is safer; aim below about 15 cmH2O.'],
  ['Resistance', '(Peak - plateau) / inspiratory flow in L/s, in volume control with constant flow. Normal ventilated adult 5-10 (includes tube); obstructive disease 15-30 or more.'],
  ['Time constant', 'Resistance x compliance (s). The lung is about 95% full or empty after 3 time constants, 99% after 5. COPD 1.5 s or more means 4.5 s or more to empty. The RCexp number on the screen is measured from the expiratory flow.'],
  ['Auto-PEEP', 'Total PEEP (expiratory hold) - set PEEP. If the flow trace does not reach zero before the next breath, it is present.'],
  ['Minute ventilation', 'VT x rate. Predicted need about 100 mL/min per kg predicted body weight, so a starting rate is (100 x PBW) / VT.'],
  ['PaCO2 (steady state)', '863 x CO2 production / (minute ventilation x (1 - dead space fraction)), with CO2 production in mL/min and ventilation in mL/min. Halve the alveolar ventilation and PaCO2 doubles, after about 15-30 minutes.'],
  ['Alveolar gas equation', 'PAO2 = FiO2 x (760 - 47) - PaCO2 / 0.8. A-a gradient = PAO2 - PaO2. P/F ratio = PaO2 / FiO2: under 300 mild, 200 moderate, 100 severe ARDS (with PEEP 5 or more).'],
  ['Winter formula', 'Expected PaCO2 = 1.5 x HCO3 + 8 (plus or minus 2) in metabolic acidosis.'],
  ['RSBI', 'Respiratory rate / tidal volume in litres, on a spontaneous trial. Below about 105 favors success.'],
  ['Stress index', 'Shape of the pressure-time curve during constant-flow volume control, fitted as pressure = a x time^b + c. b below 0.9 suggests ongoing recruitment (consider more PEEP), 0.9-1.1 linear, above 1.1 overdistension (consider less PEEP or volume). Needs a passive patient. A research aid, not a rule.'],
  ['P0.1', 'Drop in airway pressure in the first 100 ms of an occluded inspiratory effort: a measure of drive, independent of the ventilator. About 1-3 cmH2O is usual; above about 4-5 suggests high drive, below about 1 suggests over-support or weak drive.'],
];

const TEACH = [
  'Pick one asynchrony in Examples, ask learners to name it from the waveforms alone, then turn on Show Pmus to confirm.',
  'Use Share link to send a setup to a class. The learner link hides the patient and example panels so learners must work out the problem. Add "hide pressures" to remove the numbers and force waveform reading.',
  'Use Freeze on the waveform, then click to place a crosshair that reads pressure, flow and volume at the same instant. Useful for measuring time to trigger or the size of a pressure dip.',
  'Use the Fullscreen button for projection. Use the Window slider to zoom to 6 s for a single breath or out to 30 s for a pattern.',
  'Use Scenarios for individual practice, and Reset to repeat. The score is local to the browser and is not for assessment.',
  'Let learners predict before they change a setting: what will happen to peak pressure, plateau, VT, PaCO2? Then change it and check. Remember PaCO2 needs time acceleration to settle.',
];

const ASYN_TABLE_NOTE = 'Each of these is produced by the physics engine from patient and ventilator settings. Open Examples in the simulator to load any of them live.';

const PEARLS = [
  'Always set VT from predicted body weight. A short, obese patient has small lungs.',
  'Peak minus plateau tells you about resistance. Plateau minus PEEP tells you about compliance. Do the hold before you guess.',
  'Plateau is only meaningful if the patient is passive and the hold reaches a steady value. If it keeps falling, say how long you held.',
  'If the flow trace does not reach zero before the next breath, there is auto-PEEP. Lower the rate or Ti first, treat the airway, then think about PEEP.',
  'Hypotension after intubation or bagging in COPD or asthma: suspect auto-PEEP before anything else. Disconnecting the circuit for a few seconds is both a test and a treatment.',
  'In volume control, a scooped pressure waveform means the patient wants more flow than you are giving.',
  'In pressure control the set pressure is not the delivered volume. Alarm on exhaled VT: a falling VT is the first sign of worsening compliance or resistance.',
  'Adaptive modes quietly raise pressure to hold VT. A creeping pressure trend can hide a developing pneumothorax or secretions.',
  'PaCO2 is set by alveolar ventilation and the CO2 store takes about 15-30 minutes to equilibrate. Do not chase the first ABG after a change.',
  'A chronic CO2 retainer has a high bicarbonate. Correcting PaCO2 to 40 makes them alkalotic; target their baseline pH.',
  'Extrinsic PEEP only helps trigger when there is expiratory flow limitation. Without it, PEEP just adds hyperinflation.',
  'Raising PEEP can improve oxygenation by recruiting lung or worsen it by overdistending healthy units. Check plateau, driving pressure and blood pressure after each step.',
  'Reverse triggering looks like a patient fighting the ventilator but is actually the ventilator driving the diaphragm. It is easy to miss without an esophageal or Pmus signal.',
  'A "faster than set" total rate with no Pmus bump on a quiet patient points to auto-triggering: check cardiac oscillation, leaks and condensation before sedating.',
  'In passive volume control, peak pressure that is lower than expected or a sagging pressure curve suggests the patient is helping. Plateau measured then is unreliable.',
  'Cycle-off percentage is the main fix for late and early cycling in pressure support. Obstructed patients need a high percentage, restrictive patients a low one.',
  'Treat the patient, then the number. Every value here is simulated. Check your local protocols.',
];

const table = (rows, head) => `<table><tr><th>${head[0]}</th><th>${head[1]}</th></tr>${rows.map(([a, b]) => `<tr><td><b>${a}</b></td><td>${b}</td></tr>`).join('')}</table>`;

export function renderLearn(box) {
  box.innerHTML = `<div class="prose">
<h2>Learn</h2>
<p class="muted">Draft teaching content, not yet clinically reviewed. Numbers are common published targets; always follow your local protocols.</p>
<div class="quick"><b>Quick start (60 seconds)</b>
<ol>
<li>Open the <b>Simulator</b> tab and choose a patient (lung type, sex, height) in the <b>Patient</b> bar at the top, or press <b>New patient...</b>.</li>
<li>Press <b>Controls</b> on the right to change the mode, tidal volume or pressure, rate, PEEP and oxygen. The round dials show the main ones.</li>
<li>Watch what happens to the <b>waveforms</b>, the <b>lungs</b> and the <b>loops</b>. Press <b>Insp hold</b> to read plateau pressure, <b>Exp hold</b> to read auto-PEEP, and <b>Get ABG</b> for a blood gas.</li>
<li>Stuck? Hover over any number for a one-line explanation, open <b>Examples</b> to see common problems, or try a <b>Scenario</b> for guided practice with hints.</li>
</ol></div>
<p><a href="#l-use">How to use</a> | <a href="#l-screen">The screen</a> | <a href="#l-set">Settings</a> | <a href="#l-targets">Targets</a> | <a href="#l-strat">Strategies</a> | <a href="#l-wave">Expected waveforms</a> | <a href="#l-async">Asynchrony</a> | <a href="#l-calc">Formulas</a> | <a href="#l-teach">Teaching with it</a> | <a href="#l-pearls">Pearls</a></p>

<h3 id="l-use">How to use this simulator</h3>
<ol>
<li>Pick a <b>lung type</b> in Controls &gt; Patient (Normal, COPD, ARDS). Press <b>Reset</b> to start over at any time.</li>
<li>Open <b>Controls</b> (right side) to change settings. The three round dials show the main targets; click one to edit.</li>
<li>Watch the <b>waveforms</b> (pressure and flow), the <b>lungs</b> and the two <b>loops</b>. Everything you see is computed from physics, not scripted.</li>
<li>Use <b>Insp hold</b> (volume control) to read plateau, and <b>Exp hold</b> to read total PEEP. The measurement panel under the screen shows compliance, resistance and driving pressure after a hold.</li>
<li>Press <b>ABG</b> for a blood gas. CO2 takes simulated minutes to change: use the time buttons (5x, 20x, 60x). Waveforms pause above 5x.</li>
<li>Tick <b>Show the physics</b> under the screen to see elastic, resistive, viscoelastic and patient-effort pressures.</li>
<li>Go to <b>Scenarios</b> for 10 troubleshooting cases with questions, hints and scoring.</li>
</ol>

<h3 id="l-screen">Reading the screen</h3>
<ul>
<li><b>Left column (big numbers):</b> Ppeak (peak pressure; small numbers are alarm limit and PEEP), minute volume, exhaled VT (small number: set VT), total rate (small number: set rate), RCexp (measured expiratory time constant, seconds: how slowly the lung empties; above about 1 s means slow emptying), and SpO2.</li>
<li><b>Waveforms:</b> airway pressure, flow (above zero = inspiration) and volume.</li>
<li><b>Lungs:</b> size follows volume (exaggerated), colour follows elastic stress (blue low, red high), airway width follows resistance, the line under the lungs is the diaphragm and lights up with patient effort. A one-sided pneumothorax collapses the lung on that side.</li>
<li><b>P-V loop:</b> pressure on the horizontal axis, volume vertical. A flatter loop = stiffer lung. A wider loop = more resistance. The white line joins start and peak (dynamic compliance). Save a reference loop to compare after a change.</li>
<li><b>Flow-volume loop:</b> inspiration above zero, expiration below. Scooping and flow that does not return to zero suggest obstruction and auto-PEEP.</li>
<li><b>Bottom bar:</b> Monitoring (main screen), Tools, Events (log), Patient.</li>
</ul>

<h3 id="l-set">Settings and what they represent</h3>
${table(SETTINGS, ['Setting', 'Meaning and effect'])}

<h3 id="l-targets">Ventilator targets</h3>
${table(TARGETS, ['Parameter', 'Common target'])}

<h3 id="l-strat">Strategies</h3>
${table(STRATEGIES, ['Situation', 'Approach'])}

<h3 id="l-wave">Expected waveforms (generated live by this simulator)</h3>
<div id="gallery" class="gallery"></div>

<h3 id="l-async">Patient-ventilator asynchrony</h3>
<p>${ASYN_TABLE_NOTE}</p>
<div id="agallery" class="gallery"></div>

<h3 id="l-calc">Useful calculations</h3>
${table(FORMULAS, ['Quantity', 'Definition and use'])}

<h3 id="l-teach">Teaching with this simulator</h3>
<ul>${TEACH.map((p) => `<li>${p}</li>`).join('')}</ul>
<p class="muted">What the simulator does not teach (yet): recruitability and the recruitment-to-inflation ratio, airway closure and opening pressure, proportional assist, esophageal pressure and a two-compartment lung with pendelluft. These are described in the Model and limits tab.</p>

<h3 id="l-pearls">Clinical pearls</h3>
<ul>${PEARLS.map((p) => `<li>${p}</li>`).join('')}</ul>
<p class="muted">Educational use only. Not for clinical decision-making.</p>
</div>`;
  // Draw the gallery lazily so the tab opens instantly.
  const g = box.querySelector('#gallery');
  requestAnimationFrame(() => {
    for (const item of GALLERY) {
      const sim = new Sim(item.key, item.mods || {}, item.set); sim.rec = false; sim.run(60); sim.rec = true; sim.out.length = 0;
      if (item.hold) sim.s.holdReq = true;
      sim.run(15);
      const cv = document.createElement('canvas'); cv.className = 'gcanvas';
      const fig = document.createElement('figure'); fig.innerHTML = `<figcaption><b>${item.t}</b></figcaption>`;
      fig.append(cv); const p = document.createElement('p'); p.textContent = item.look; fig.append(p); g.append(fig);
      drawStrip(cv, sim.out, { seconds: 15 });
    }
    const ag = box.querySelector('#agallery');
    for (const a of ASYN) {
      const sim = new Sim(a.key, a.mods, a.set); sim.rec = false; sim.run(60); sim.rec = true; sim.out.length = 0; sim.run(18);
      const cv = document.createElement('canvas'); cv.className = 'gcanvas';
      const fig = document.createElement('figure'); fig.innerHTML = `<figcaption><b>${a.title}</b></figcaption>`;
      fig.append(cv);
      for (const [lab, txt] of [['What it is', a.what], ['What you see (dashed = patient effort)', a.look], ['What to do', a.fix]]) { const p = document.createElement('p'); p.innerHTML = `<b>${lab}:</b> `; p.append(txt); fig.append(p); }
      ag.append(fig);
      drawStrip(cv, sim.out, { seconds: 18, pmus: true, peep: a.set.peep ?? 5 });
    }
  });
}
